before:
Complete local Rust example; the app itself does not execute it:
```rust
use std::{fs, io};
fn save_and_read(path: &str) -> io::Result<String> {
    fs::write(path, "ready")?;
    fs::read_to_string(path)
}
fn main() {
    match save_and_read("notes.txt") {
        Ok(text) => println!("{text}"),
        Err(_) => println!("I/O failed"),
    }
}
```

